package ec.edu.unl.sec.evidence.domain;
import java.time.*;import java.util.*;
public record EvidenceVersion(UUID id,UUID evidenceId,int revisionNumber,UUID predecessorId,EvidenceVersionStatus status,String title,String description,String provenance,LocalDate coveredFrom,LocalDate coveredTo,UUID authorId,Instant createdAt,Instant submittedAt,long lockRevision,List<VersionIndicator> indicators){public EvidenceVersion{id=id==null?UUID.randomUUID():id;Objects.requireNonNull(evidenceId);if(revisionNumber<1)throw new IllegalArgumentException("revision must be positive");if((revisionNumber==1)!=(predecessorId==null))throw new IllegalArgumentException("invalid predecessor");status=status==null?EvidenceVersionStatus.DRAFT:status;title=text(title,300);description=text(description,8000);provenance=text(provenance,4000);if(coveredFrom==null||coveredTo==null||coveredFrom.isAfter(coveredTo))throw new IllegalArgumentException("invalid covered period");Objects.requireNonNull(authorId);createdAt=createdAt==null?Instant.now():createdAt;if(lockRevision<0)throw new IllegalArgumentException("lock revision must be non-negative");indicators=indicators==null?List.of():List.copyOf(indicators);if(indicators.isEmpty())throw new IllegalArgumentException("indicator required");if(indicators.stream().map(VersionIndicator::indicatorId).distinct().count()!=indicators.size())throw new IllegalArgumentException("duplicate indicator");if(status==EvidenceVersionStatus.SUBMITTED&&submittedAt==null)throw new IllegalArgumentException("submission time required");}public EvidenceVersion update(String title,String description,String provenance,LocalDate from,LocalDate to,List<VersionIndicator> indicators){requireDraft();return new EvidenceVersion(id,evidenceId,revisionNumber,predecessorId,status,title,description,provenance,from,to,authorId,createdAt,null,lockRevision+1,indicators);}public EvidenceVersion submit(Instant submittedAt){Objects.requireNonNull(submittedAt,"submission time required");requireDraft();return new EvidenceVersion(id,evidenceId,revisionNumber,predecessorId,EvidenceVersionStatus.SUBMITTED,title,description,provenance,coveredFrom,coveredTo,authorId,createdAt,submittedAt,lockRevision+1,indicators);}private void requireDraft(){if(status!=EvidenceVersionStatus.DRAFT)throw new IllegalStateException("submitted version is immutable");}private static String text(String v,int max){if(v==null||v.isBlank()||v.strip().length()>max)throw new IllegalArgumentException("invalid evidence text");return v.strip();}}
